export function computeInvoice(input) {
  const lines = input == null ? undefined : input.lines;

  if (!Array.isArray(lines)) {
    throw new RangeError("lines must be an array");
  }

  const requestedDiscountKobo =
    input.discountKobo === undefined ? 0 : input.discountKobo;

  if (
    !Number.isInteger(requestedDiscountKobo) ||
    requestedDiscountKobo < 0
  ) {
    throw new RangeError("discountKobo must be a non-negative integer");
  }

  const preparedLines = new Array(lines.length);
  let subtotal = 0n;

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const unitPriceKobo =
      line == null ? undefined : line.unitPriceKobo;
    const qty = line == null ? undefined : line.qty;

    if (!Number.isInteger(unitPriceKobo) || unitPriceKobo < 0) {
      throw new RangeError(
        `unitPriceKobo at line ${index} must be a non-negative integer`
      );
    }

    if (!Number.isInteger(qty) || qty < 1) {
      throw new RangeError(
        `qty at line ${index} must be a positive integer`
      );
    }

    const lineSubtotal = BigInt(unitPriceKobo) * BigInt(qty);
    subtotal += lineSubtotal;

    preparedLines[index] = {
      sku: line.sku,
      vatExempt: line.vatExempt,
      subtotalKobo: lineSubtotal,
    };
  }

  const requestedDiscount = BigInt(requestedDiscountKobo);
  const appliedDiscount =
    requestedDiscount < subtotal ? requestedDiscount : subtotal;

  const allocations = new Array(lines.length).fill(0n);

  if (subtotal > 0n && appliedDiscount > 0n) {
    const remainders = new Array(lines.length);
    let allocated = 0n;

    for (let index = 0; index < preparedLines.length; index += 1) {
      const product =
        appliedDiscount * preparedLines[index].subtotalKobo;
      const allocation = product / subtotal;

      allocations[index] = allocation;
      allocated += allocation;
      remainders[index] = {
        index,
        remainder: product % subtotal,
      };
    }

    let leftover = appliedDiscount - allocated;

    if (leftover > 0n) {
      remainders.sort((a, b) => {
        if (a.remainder === b.remainder) {
          return a.index - b.index;
        }
        return a.remainder > b.remainder ? -1 : 1;
      });

      for (let rank = 0; leftover > 0n; rank += 1) {
        allocations[remainders[rank].index] += 1n;
        leftover -= 1n;
      }
    }
  }

  let vat = 0n;

  const resultLines = preparedLines.map((line, index) => {
    const lineDiscount = allocations[index];
    const net = line.subtotalKobo - lineDiscount;
    const lineVat = line.vatExempt
      ? 0n
      : (net * 3n + 20n) / 40n;

    vat += lineVat;

    return {
      sku: line.sku,
      subtotalKobo: Number(line.subtotalKobo),
      discountKobo: Number(lineDiscount),
      netKobo: Number(net),
      vatKobo: Number(lineVat),
    };
  });

  const total = subtotal - appliedDiscount + vat;

  return {
    subtotalKobo: Number(subtotal),
    discountKobo: Number(appliedDiscount),
    vatKobo: Number(vat),
    totalKobo: Number(total),
    lines: resultLines,
  };
}
